# Independent disassembler for the proof audit (clean-room).
code = open('/home/dmn/kit-example/examples/01-transfer/contract/StandardToken.inlined.bytes').read().strip()[2:]
b = bytes.fromhex(code)
op = {0x00:'STOP',0x01:'ADD',0x03:'SUB',0x04:'DIV',0x10:'LT',0x11:'GT',0x14:'EQ',0x15:'ISZERO',0x16:'AND',
0x20:'SHA3',0x34:'CALLVALUE',0x35:'CALLDATALOAD',0x36:'CALLDATASIZE',0x50:'POP',0x51:'MLOAD',0x52:'MSTORE',
0x54:'SLOAD',0x55:'SSTORE',0x56:'JUMP',0x57:'JUMPI',0x5b:'JUMPDEST',0x33:'CALLER',0xf3:'RETURN',0xfd:'REVERT',0xa3:'LOG3'}
for i in range(0x60,0x80): op[i]=f'PUSH{i-0x5f}'
for i in range(0x80,0x90): op[i]=f'DUP{i-0x7f}'
for i in range(0x90,0xa0): op[i]=f'SWAP{i-0x8f}'
def disasm(lo,hi):
    i=lo; out=[]
    while i<hi and i<len(b):
        o=b[i]; name=op.get(o,f'op_{o:02x}')
        if 0x60<=o<=0x7f:
            n=o-0x5f; data=b[i+1:i+1+n]; out.append((i,name,'0x'+data.hex())); i+=1+n
        else:
            out.append((i,name,'')); i+=1
    return out
# dispatcher: find selector a9059cbb
print("=== dispatcher selector match ===")
for (pc,n,a) in disasm(0x30,0x70):
    if a and a.endswith('a9059cbb'): print(f"  {pc:04x} {n} {a}  (transfer selector)")
    if n.startswith('PUSH') and a in ('0x0192',): print(f"  {pc:04x} {n} {a}  (jump target)")
print("=== transfer entry 0x192.. (non-payable guard) ===")
for (pc,n,a) in disasm(0x192,0x1a0): print(f"  {pc:04x} {n} {a}")
print("=== key-hash + condition 0x60f..0x666 (slot for balances) ===")
for (pc,n,a) in disasm(0x60f,0x666): print(f"  {pc:04x} {n} {a}")
print("=== false branch target 0x76d.. ===")
for (pc,n,a) in disasm(0x76d,0x778): print(f"  {pc:04x} {n} {a}")
print("=== recipient add region 0x6f0..0x700 ===")
for (pc,n,a) in disasm(0x6f0,0x700): print(f"  {pc:04x} {n} {a}")

